void audition(){for(auto workers:{1U,2U,4U}){auto e=std::make_shared<AudioEngine>();RenderGraph g;g.mixer.resize(1);g.inserts={synth()};g.live_midi={true};g.midi_monitor={false};e->prepare({48000,0,2,128,128,workers},g);const auto gen=e->midi_generation();std::array<float,256> out{};
    CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));allocations=0;probe=true;e->process(nullptr,out.data(),128);probe=false;CHECK(allocations==0&&out.back()==.25f);
    CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0}));e->process(nullptr,out.data(),128);CHECK(out.back()==0);
    CHECK(e->enqueue_audition_midi({gen-1,0,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),128);CHECK(out.back()==0);
    CHECK(e->enqueue_audition_midi({gen,9,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),128);CHECK(out.back()==0);
    for(int i=0;i<127;++i)CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));CHECK(!e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0}));e->process(nullptr,out.data(),128);CHECK(out.back()==0);
}}
void audition_tail(){for(auto rate:{44100U,48000U,96000U})for(auto workers:{1U,4U}){auto e=std::make_shared<AudioEngine>();RenderGraph g;g.mixer.resize(1);g.inserts={synth(rate)};g.live_midi={true};g.midi_monitor={true};e->prepare({rate,0,2,256,128,workers},g);const auto gen=e->midi_generation();std::array<float,512> out{};CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),256);CHECK(out.back()==.25f);CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0,70}));float last=.25f;bool faded=false;allocations=0;probe=true;for(unsigned block=0;block<rate/256/10+4;++block){e->process(nullptr,out.data(),256);for(std::size_t i=0;i<out.size();i+=2){CHECK(out[i]<=last+.000001f&&out[i]>=0&&last-out[i]<.001f);if(out[i]>.001f&&out[i]<.24f)faded=true;last=out[i];}}probe=false;CHECK(faded&&last==0&&allocations==0);CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),256);CHECK(out.back()==.25f);CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0,70}));e->process(nullptr,out.data(),256);CHECK(out.back()==.25f);CHECK(e->enqueue_live_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),256);CHECK(out.back()==.25f);CHECK(e->enqueue_live_midi({gen,0,{0,MidiKind::note_off,0,60,0},0}));e->process(nullptr,out.data(),256);CHECK(out.back()==0);CHECK(e->enqueue_live_midi({gen,0,{0,MidiKind::note_on,0,64,127},0}));CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0}));e->process(nullptr,out.data(),256);CHECK(out.back()==.5f);CHECK(e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0,70}));e->process(nullptr,out.data(),256);CHECK(out.back()==.25f);}}
void audition_not_recorded(){auto e=std::make_shared<AudioEngine>();RenderGraph g;g.mixer.resize(1);g.inserts={synth()};g.live_midi={true};auto recorder=std::make_shared<MidiRecorder>(0);g.midi_recordings={{0,recorder}};e->prepare({48000,0,2,128,128,2},g);const auto gen=e->midi_generation();std::array<float,256> out{};e->enqueue({ControlKind::play});e->enqueue_audition_midi({gen,0,{0,MidiKind::note_on,0,60,127},0});e->process(nullptr,out.data(),128);CHECK(out.back()==.25f);e->enqueue_audition_midi({gen,0,{0,MidiKind::note_off,0,60,0},0});e->process(nullptr,out.data(),128);CHECK(out.back()==0);const auto take=recorder->finish(Timeline(TimeMap{},48000));CHECK(take.notes.empty()&&take.events.empty());}
void application(const std::filesystem::path& fixture){Directory dir;const auto plugin=dir.path/"instrument.vst3";std::filesystem::copy_file(fixture,plugin);auto u=plugin.u8string();auto info=probe_vst3(std::string(u.begin(),u.end())).front();NativeInsert fx;fx.id=new_id();fx.kind=InsertKind::vst3;fx.plugin_path=info.path;fx.class_id=info.class_id;fx.plugin_name=info.name;
    Application a;a.new_project();auto track=a.add_instrument_track("Keys");a.set_inserts(track,{fx});a.connect(std::make_unique<ManualDevice>(),{0,48000,128,{}, {0,1},2});auto clip=a.create_midi_clip(track,0,4*ppq);a.set_midi_notes(clip,{{new_id(),0,ppq,60,127,0}});auto time=a.services().projects->state().project->time;time.tempos={{0,60}};a.set_time_map(time);CHECK(a.services().projects->state().project->clips.front().midi->length==4*ppq);CHECK(a.undo());CHECK(a.redo());CHECK(a.undo());a.play();std::array<float,256> out{};a.engine()->process(nullptr,out.data(),128);CHECK(out.back()>.2f);rejects([&]{a.remove_clip(clip);});a.pause();a.engine()->process(nullptr,out.data(),128);a.poll();CHECK(out.back()==0);a.seek(24000);a.engine()->process(nullptr,out.data(),128);a.poll();a.split_clip(clip,24000);CHECK(a.services().projects->state().project->clips.size()==2);CHECK(a.undo());CHECK(a.redo());CHECK(a.undo());a.duplicate_clip(clip);CHECK(a.undo());
    const auto file=dir.path/"song.mrsproject";a.save_project(file);a.save_project(dir.path/"copy"/"song.mrsproject");a.open_project(file);CHECK(a.services().projects->state().project->clips[0].midi->notes.size()==1);a.connect(std::make_unique<ManualDevice>(),{0,48000,128,{}, {0,1},2});a.play();a.engine()->process(nullptr,out.data(),128);check(out.back()>.2f,"reopened MIDI clip audio");a.pause();a.engine()->process(nullptr,out.data(),128);a.poll();auto audioTrack=a.add_audio_track("Raw input");a.set_track_input(audioTrack,0);a.connect(std::make_unique<ManualDevice>(),{0,48000,128,{0}, {0,1},2});a.set_track_armed(audioTrack,true);a.start_recording(dir.path/"raw.wav");std::array<float,128> input;input.fill(.125f);a.engine()->process(input.data(),out.data(),128);a.stop_recording();CHECK(a.services().projects->state().project->clips.size()==2);auto raw=open_wav(dir.path/"raw.wav");CHECK(raw.frames()==128&&std::abs(raw.samples[0]-.125f)<.00001f);a.disconnect();
}
