void* operator new(std::size_t n){if(probe)++allocations;if(auto p=std::malloc(n?n:1))return p;throw std::bad_alloc{};}void operator delete(void* p)noexcept{std::free(p);}void operator delete(void* p,std::size_t)noexcept{std::free(p);}
int main(int argc,char** argv){try{CHECK(argc==2);model();musical();controllers();controller_budget();schedule();engine();audition();audition_tail();audition_not_recorded();application(argv[1]);std::cout<<"PASS MIDI clips\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
